class TransactionV2DetailsView extends ConsumerStatefulWidget {
  const TransactionV2DetailsView({
    super.key,
    required this.transaction,
    required this.walletId,
    required this.coin,
  });

  static const String routeName = "/transactionV2Details";

  final TransactionV2 transaction;
  final String walletId;
  final CryptoCurrency coin;

  @override
  ConsumerState<TransactionV2DetailsView> createState() =>
      _TransactionV2DetailsViewState();
}

class _TransactionV2DetailsViewState
    extends ConsumerState<TransactionV2DetailsView> {
  late final bool isDesktop;
  late TransactionV2 _transaction;
  late final String walletId;

  late final CryptoCurrency coin;

  /// PIVX: received shield notes carried a text memo.
  bool get _hasPivxMemo =>
      coin is Pivx && (_transaction.onChainNote?.isNotEmpty ?? false);
  late final Amount amount;
  late final Amount fee;
  late final String amountPrefix;
  late final String unit;
  late final int minConfirms;

  late List<({List<String> addresses, Amount amount, bool coldStake})> data;

  bool showFeePending = false;

  @override
  void initState() {
    isDesktop = Util.isDesktop;
    _transaction = widget.transaction;
    walletId = widget.walletId;

    coin = widget.coin;
    unit = coin.ticker;

    minConfirms = ref
        .read(pWallets)
        .getWallet(walletId)
        .cryptoCurrency
        .minConfirms;

    final fractionDigits = coin.fractionDigits;

    fee = _transaction.getFee(fractionDigits: fractionDigits);

    amountPrefix = switch (_transaction.type) {
      TransactionType.sentToSelf => "",
      TransactionType.outgoing => "-",
      _ => "+",
    };

    switch (_transaction.type) {
      case TransactionType.outgoing:
      case TransactionType.unknown:
        amount = _transaction.getAmountSentFromThisWallet(
          fractionDigits: fractionDigits,
          subtractFee: true,
        );
        break;

      case TransactionType.incoming:
      case TransactionType.sentToSelf:
        amount = _transaction.getAmountReceivedInThisWallet(
          fractionDigits: fractionDigits,
        );
        break;
    }

    // Like PIVX Core: the destination only, without change. All inputs
    // and outputs are listed separately ([_PivxTxParts]).
    final change = _transaction.pivxChangeAddresses;
    final owned = _transaction.outputs.where((e) => e.walletOwns);
    var shown = switch (_transaction.type) {
      TransactionType.outgoing => _transaction.outputs.where(
        (e) => !e.walletOwns,
      ),
      TransactionType.incoming => owned,
      _ => owned.where((e) => !e.addresses.any(change.contains)),
    };
    if (shown.isEmpty) shown = owned;
    data = [
      for (final e in shown)
        (
          addresses: e.addresses,
          amount: Amount(rawValue: e.value, fractionDigits: fractionDigits),
          // A delegated output: staker and owner, one amount.
          coldStake:
              pivxIsColdStakeScript(e.scriptPubKeyHex) &&
              e.addresses.length == 2,
        ),
    ];

    super.initState();
  }

  @override
  void dispose() {
    super.dispose();
  }

  String whatIsIt(TransactionV2 tx, int height) => tx.statusLabel(
    currentChainHeight: height,
    minConfirms: minConfirms,
    minCoinbaseConfirms: ref
        .read(pWallets)
        .getWallet(walletId)
        .cryptoCurrency
        .minCoinbaseConfirms,
  );

  Future<String> fetchContactNameFor(String address) async {
    if (address.isEmpty) {
      return address;
    }
    try {
      final contacts = ref
          .read(addressBookServiceProvider)
          .contacts
          .where(
            (element) => element.addresses
                .where((element) => element.address == address)
                .isNotEmpty,
          );
      if (contacts.isNotEmpty) {
        return contacts.first.name;
      } else {
        return address;
      }
    } catch (e, s) {
      Logging.instance.w("$e\n$s", error: e, stackTrace: s);
      return address;
    }
  }

