class _TxidDetailItemState extends ConsumerState<_TxidDetailItem> {
  Future<bool> showExplorerWarning(String explorer) async {
    final warningMessage =
        "You are about to view this transaction in a block explorer. "
        "The explorer may log your IP address and link it to the "
        "transaction. Only proceed if you trust $explorer.";

    final bool? shouldContinue = await showDialog<bool>(
      context: context,
      barrierDismissible: false,
      builder: (_) {
        if (!Util.isDesktop) {
          return StackDialog(
            title: "Attention",
            message: warningMessage,
            icon: Row(
              children: [
                Consumer(
                  builder: (_, ref, __) {
                    return Checkbox(
                      value: ref.watch(
                        prefsChangeNotifierProvider.select(
                          (value) => value.hideBlockExplorerWarning,
                        ),
                      ),
                      onChanged: (value) {
                        if (value is bool) {
                          ref
                                  .read(prefsChangeNotifierProvider)
                                  .hideBlockExplorerWarning =
                              value;
                          setState(() {});
                        }
                      },
                    );
                  },
                ),
                Text(
                  "Never show again",
                  style: STextStyles.smallMed14(context),
                ),
              ],
            ),
            leftButton: TextButton(
              onPressed: () {
                Navigator.of(context).pop(false);
              },
              child: Text(
                "Cancel",
                style: STextStyles.button(context).copyWith(
                  color: Theme.of(context)
                      .extension<StackColors>()!
                      .accentColorDark,
                ),
              ),
            ),
            rightButton: TextButton(
              style: Theme.of(context)
                  .extension<StackColors>()!
                  .getPrimaryEnabledButtonStyle(context),
              onPressed: () {
                Navigator.of(context).pop(true);
              },
              child: Text("Continue", style: STextStyles.button(context)),
            ),
          );
        } else {
          return DesktopDialog(
            maxWidth: 550,
            maxHeight: 300,
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 32, vertical: 20),
              child: Column(
                children: [
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Text("Attention", style: STextStyles.desktopH2(context)),
                      Row(
                        children: [
                          Consumer(
                            builder: (_, ref, __) {
                              return Checkbox(
                                value: ref.watch(
                                  prefsChangeNotifierProvider.select(
                                    (value) => value.hideBlockExplorerWarning,
                                  ),
                                ),
                                onChanged: (value) {
                                  if (value is bool) {
                                    ref
                                            .read(prefsChangeNotifierProvider)
                                            .hideBlockExplorerWarning =
                                        value;
                                    setState(() {});
                                  }
                                },
                              );
                            },
                          ),
                          Text(
                            "Never show again",
                            style: STextStyles.smallMed14(context),
                          ),
                        ],
                      ),
                    ],
                  ),
                  const SizedBox(height: 16),
                  Text(
                    warningMessage,
                    style: STextStyles.desktopTextSmall(context),
                  ),
                  const SizedBox(height: 35),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      SecondaryButton(
                        width: 200,
                        buttonHeight: ButtonHeight.l,
                        label: "Cancel",
                        onPressed: () {
                          Navigator.of(context, rootNavigator: true).pop(false);
                        },
                      ),
                      const SizedBox(width: 20),
                      PrimaryButton(
                        width: 200,
                        buttonHeight: ButtonHeight.l,
                        label: "Continue",
                        onPressed: () {
                          Navigator.of(context, rootNavigator: true).pop(true);
                        },
                      ),
                    ],
                  ),
                ],
              ),
            ),
          );
        }
      },
    );
    return shouldContinue ?? false;
  }

  @override
  Widget build(BuildContext context) {
    final isDesktop = Util.isDesktop;

    return _DetailItemBase(
      child:
          widget.txid.startsWith("mweb_outputId_") &&
              widget.subType == TransactionSubType.mweb
          ? Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,

                    children: [
                      ConditionalParent(
                        condition: !isDesktop,
                        builder: (child) => Row(
                          children: [
                            Expanded(child: child),
                            SimpleCopyButton(
                              data: widget.txid.replaceFirst(
                                "mweb_outputId_",
                                "",
                              ),
                            ),
                          ],
                        ),
                        child: Text(
                          "MWEB Output ID",
                          style: isDesktop
                              ? STextStyles.desktopTextExtraExtraSmall(context)
                              : STextStyles.itemSubtitle(context),
                        ),
                      ),
                      const SizedBox(height: 8),
                      SelectableText(
                        widget.txid.replaceFirst("mweb_outputId_", ""),
                        style: isDesktop
                            ? STextStyles.desktopTextExtraExtraSmall(context)
                                  .copyWith(
                                    color: Theme.of(context)
                                        .extension<StackColors>()!
                                        .textDark,
                                  )
                            : STextStyles.itemSubtitle12(context),
                      ),
                    ],
                  ),
                ),
                if (isDesktop) const SizedBox(width: 12),
                if (isDesktop)
                  IconCopyButton(
                    data: widget.txid.replaceFirst("mweb_outputId_", ""),
                  ),
              ],
            )
          : Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      ConditionalParent(
                        condition: !isDesktop,
                        builder: (child) => Row(
                          children: [
                            Expanded(child: child),
                            SimpleCopyButton(data: widget.txid),
                          ],
                        ),
                        child: Text(
                          "Transaction ID",
                          style: isDesktop
                              ? STextStyles.desktopTextExtraExtraSmall(context)
                              : STextStyles.itemSubtitle(context),
                        ),
                      ),
                      const SizedBox(height: 8),

                      SelectableText(
                        widget.txid,
                        style: isDesktop
                            ? STextStyles.desktopTextExtraExtraSmall(context)
                                  .copyWith(
                                    color: Theme.of(context)
                                        .extension<StackColors>()!
                                        .textDark,
                                  )
                            : STextStyles.itemSubtitle12(context),
                      ),
                      const SizedBox(height: 8),
                      CustomTextButton(
                        text: "Open in block explorer",
                        onTap: () async {
                          final uri = getBlockExplorerTransactionUrlFor(
                            coin: widget.coin,
                            txid: widget.txid,
                          );

                          if (ref
                                  .read(prefsChangeNotifierProvider)
                                  .hideBlockExplorerWarning ==
                              false) {
                            final shouldContinue = await showExplorerWarning(
                              "${uri.scheme}://${uri.host}",
                            );

                            if (!shouldContinue || !context.mounted) {
                              return;
                            }
                          }

                          try {
                            await launchUrl(
                              uri,
                              mode: LaunchMode.externalApplication,
                            );
                          } catch (_) {
                            if (context.mounted) {
                              unawaited(
                                showDialog<void>(
                                  context: context,
                                  builder: (_) => StackOkDialog(
                                    title: "Could not open in block explorer",
                                    message:
                                        "Failed to open "
                                        "\"${uri.toString()}\"",
                                    maxWidth: Util.isDesktop ? 400 : null,
                                  ),
                                ),
                              );
                            }
                          }
                        },
                      ),
                    ],
                  ),
                ),
                if (isDesktop) const SizedBox(width: 12),
                if (isDesktop) IconCopyButton(data: widget.txid),
              ],
            ),
    );
  }
}

